#include <map>
#include <set>
#include <list>
#include <cmath>
#include <queue>
#include <stack>
#include <bitset>
#include <vector>
#include <cstdio>
#include <string>
#include <sstream>
#include <cstdlib>
#include <cstring>
#include <iostream>
#include <algorithm>
using namespace std;

const int MAXN = 210;
const int INF = 0x3f3f3f3f;

struct SAP {
    int cap[MAXN][MAXN], flow[MAXN][MAXN], g[MAXN][MAXN];
    int n;
    int h[MAXN], vh[MAXN], src, dst;
    int mk[MAXN];

    void init(int nodes) {
        this->n = nodes;
        memset(cap, 0, sizeof(cap));
        memset(g, 0, sizeof(g));
        memset(mk, 0, sizeof(mk));
    }

    void addEdge(int u, int v, int c) {
        cap[u][v] += c;
        g[u][v] = 1;
    }

    int dfs(int u, int limit) {
        if (u == dst) return limit;
        int pushed = limit, delta, minDist = n;
        for (int v = 0; v < n; ++v) {
            if (cap[u][v] - flow[u][v] > 0) {
                if (h[u] == h[v] + 1) {
                    delta = dfs(v, min(pushed, cap[u][v] - flow[u][v]));
                    flow[u][v] += delta;
                    flow[v][u] -= delta;
                    pushed -= delta;
                    if (h[src] == n || pushed == 0) return limit - pushed;
                }
                minDist = min(minDist, h[v] + 1);
            }
        }
        if (pushed == limit) {
            vh[h[u]]--;
            vh[minDist]++;
            if (vh[h[u]] == 0) h[src] = n;
            h[u] = minDist;
        }
        return limit - pushed;
    }

    int maxFlow(int s, int d) {
        if (s == d) return INF;
        dst = d; src = s;
        memset(flow, 0, sizeof(flow));
        memset(h, 0, sizeof(h));
        memset(vh, 0, sizeof(vh));
        int result = 0;
        while (h[src] != n) {
            result += dfs(src, INF);
        }
        return result;
    }
} sap;

struct Point {
    int x, y, dist;
};

int N, T;
int startX, startY;
const int dx[4] = {0, 0, -1, 1};
const int dy[4] = {-1, 1, 0, 0};
char grid1[MAXN][MAXN], grid2[MAXN][MAXN];
int dist1[MAXN][MAXN], visited[MAXN][MAXN];

int idx(int i, int j) {
    return (i - 1) * N + j;
}

bool inBounds(int x, int y) {
    return x >= 1 && x <= N && y >= 1 && y <= N;
}

void bfs1() {
    queue<Point> q;
    Point cur, nxt;
    cur.x = startX; cur.y = startY; cur.dist = 0;
    q.push(cur);
    memset(dist1, 0x7f, sizeof(dist1));
    memset(visited, 0, sizeof(visited));
    visited[cur.x][cur.y] = 1;
    while (!q.empty()) {
        cur = q.front(); q.pop();
        dist1[cur.x][cur.y] = cur.dist;
        if (cur.dist > T) break;
        for (int k = 0; k < 4; ++k) {
            int nx = cur.x + dx[k], ny = cur.y + dy[k];
            if (inBounds(nx, ny) && grid1[nx][ny] != 'Y' && !visited[nx][ny]) {
                nxt.x = nx; nxt.y = ny; nxt.dist = cur.dist + 1;
                visited[nx][ny] = 1;
                q.push(nxt);
            }
        }
    }
}

void bfs2(int i, int j) {
    queue<Point> q;
    Point cur, nxt;
    cur.x = i; cur.y = j; cur.dist = 0;
    q.push(cur);
    memset(visited, 0, sizeof(visited));
    visited[cur.x][cur.y] = 1;
    while (!q.empty()) {
        cur = q.front(); q.pop();
        if (cur.dist > T) break;
        if (dist1[cur.x][cur.y] < cur.dist) continue;
        if (dist1[cur.x][cur.y] == cur.dist && (grid2[cur.x][cur.y] < '1' || grid2[cur.x][cur.y] > '9')) continue;
        if (grid2[cur.x][cur.y] >= '1' && grid2[cur.x][cur.y] <= '9') {
            if (cur.x != i || cur.y != j) {
                sap.addEdge(idx(i, j), idx(cur.x, cur.y) + N * N, INF);
            }
            if (dist1[cur.x][cur.y] == cur.dist) continue;
        }
        for (int k = 0; k < 4; ++k) {
            int nx = cur.x + dx[k], ny = cur.y + dy[k];
            if (inBounds(nx, ny) && grid1[nx][ny] != 'Y' && !visited[nx][ny]) {
                nxt.x = nx; nxt.y = ny; nxt.dist = cur.dist + 1;
                visited[nx][ny] = 1;
                q.push(nxt);
            }
        }
    }
}

int main() {
    scanf("%d%d", &N, &T);
    for (int i = 1; i <= N; ++i) {
        scanf("%s", grid1[i] + 1);
    }
    for (int i = 1; i <= N; ++i) {
        scanf("%s", grid2[i] + 1);
    }
    int src = 0, dst = 2 * N * N + 1;
    sap.init(dst + 1);
    for (int i = 1; i <= N; ++i) {
        for (int j = 1; j <= N; ++j) {
            if (grid1[i][j] >= '1' && grid1[i][j] <= '9') {
                sap.addEdge(src, idx(i, j), grid1[i][j] - '0');
            }
            if (grid1[i][j] == 'Z') {
                startX = i; startY = j;
            }
        }
    }
    for (int i = 1; i <= N; ++i) {
        for (int j = 1; j <= N; ++j) {
            sap.addEdge(idx(i, j), idx(i, j) + N * N, INF);
            if (grid2[i][j] >= '1' && grid2[i][j] <= '9') {
                sap.addEdge(idx(i, j) + N * N, dst, grid2[i][j] - '0');
            }
        }
    }
    bfs1();
    for (int i = 1; i <= N; ++i) {
        for (int j = 1; j <= N; ++j) {
            if (grid1[i][j] >= '1' && grid1[i][j] <= '9') {
                bfs2(i, j);
            }
        }
    }
    cout << sap.maxFlow(src, dst) << endl;
    return 0;
}
